def token_entropy(probs):
    import math
    return -sum(p * math.log(p) for p in probs if p > 0)

class Node:
    def __init__(self, val):
        self.val = val
        self.next = None
    def append(self, val):
        curr = self
        while curr.next:
            curr = curr.next
        curr.next = Node(val)
